export const ATMO_VERT=`varying vec3 vWorld; void main(){ vec4 w = modelMatrix * vec4(position,1.0); vWorld = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`;
export const ATMO_FRAG=`precision highp float;
// WEBGL1: yes (GLSL ES 1.00). Shared helpers. Paste above any other snippet.
// Conventions: world units = metres, Y up, all lighting in LINEAR space, output converted to sRGB at the end.
#define PI 3.14159265359
vec3 srgbToLinear(vec3 c){ return pow(c, vec3(2.2)); }
vec3 linearToSrgb(vec3 c){ return pow(max(c, vec3(0.0)), vec3(1.0/2.2)); }
// object-space unit direction -> equirect uv (u = atan2(z,-x)/2pi, v = acos(y)/pi, v=0 = north pole = TOP row).
// SEAM NOTE: fract(atan) has a derivative spike on the u=0/1 line -> only use it with textures that have NO mipmaps
// (minFilter = LinearFilter), e.g. the cloud map in cloud_shadow(). Surface sampling uses the mesh UV (seam-safe).
vec2 dirToUv(vec3 d){
  float a = atan(d.z, -d.x + 1e-6);
  return vec2(fract(a * 0.15915494), acos(clamp(d.y, -1.0, 1.0)) * 0.31830989);
}
// analytic tangent frame of the equirect sphere (so no TANGENT attribute / derivatives needed): T = east (+u), B = north (-v)
void sphereFrame(vec3 n, out vec3 T, out vec3 B){
  T = normalize(vec3(n.z, 0.0, -n.x) + vec3(1e-5, 0.0, 0.0));
  B = cross(n, T);
}
float rayleighPhase(float c){ return 0.75 * (1.0 + c * c); }
float miePhase(float c, float g){ float g2 = g * g; return (1.0 - g2) / pow(1.0 + g2 - 2.0 * g * c, 1.5) * 0.119; }

varying vec3 vWorld;
uniform vec3 uPlanetCenter; uniform float uPlanetR; uniform float uShellR;
uniform vec3 uSunDir; uniform vec3 uSunColor;
uniform vec3 uSkyColor; uniform vec3 uTwilightColor;
uniform float uDensity;   // ~0.18 (center haze ~0.16, limb ~0.7)
uniform float uMie;       // forward-scatter halo strength, 0.3..1.0
uniform float uOpacity;   // 0..1 master (fade with zoom)
void main(){
  vec3 ro = cameraPosition - uPlanetCenter;
  vec3 rd = normalize(vWorld - cameraPosition);
  float b = dot(ro, rd), c = dot(ro, ro);
  float ds = b * b - (c - uShellR * uShellR);
  if (ds <= 0.0) discard;
  float sq = sqrt(ds);
  float t0 = max(-b - sq, 0.0), t1 = -b + sq;
  float dp = b * b - (c - uPlanetR * uPlanetR);
  if (dp > 0.0) { float tp = -b - sqrt(dp); if (tp > 0.0) t1 = min(t1, tp); }   // ray ends on the planet surface
  float path = max(t1 - t0, 0.0) / (uShellR - uPlanetR);                          // in shell thicknesses
  vec3 pm = ro + rd * (0.5 * (t0 + t1));
  vec3 n = normalize(pm);
  float ndl = dot(n, uSunDir);
  float lit = smoothstep(-0.25, 0.45, ndl);
  float cs = dot(uSunDir, rd);                  // 1 = looking toward the sun (forward scatter), -1 = away
  float tw = exp(-pow(ndl / 0.22, 2.0));
  vec3 sky = mix(uSkyColor, uTwilightColor, tw);
  float amt = 1.0 - exp(-uDensity * path);
  vec3 col = (sky * rayleighPhase(cs) * 0.55 + uSunColor * miePhase(cs, 0.76) * uMie) * lit * amt;
  gl_FragColor = vec4(col * uOpacity, 1.0);     // additive: alpha unused
}
`;
